<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {formatBytes} from './format-bytes';
const props=defineProps<{batchId:string;disabled:boolean;revision?:number}>(),emit=defineEmits<{authenticationRequired:[]}>();
type Totals={sample_count:string;payload_bytes_read:string;timed_payload_bytes_read:string;active_nanos:string;zero_duration_samples:string;average_bytes_per_second:string|null};
type Estimate={attempt_id:string;planned_payload_bytes:string;confirmed_payload_bytes:string;remaining_payload_bytes:string;estimated_request_nanos:string;basis_sample_count:string;basis_timed_payload_bytes:string;basis_active_nanos:string};
type Statistics=Totals&{batch_id:string;observed_at_utc:string;total_items:number;items:(Totals&{item_id:string;path:string;current_estimate?:Estimate})[]};
const expanded=ref(false),data=ref<Statistics|null>(null),loading=ref(false),error=ref(''),page=ref(0);
const visible=computed(()=>data.value?.items.slice(page.value*100,(page.value+1)*100)||[]);
let active=true,generation=0,controller:AbortController|undefined;
const counters=['sample_count','payload_bytes_read','timed_payload_bytes_read','active_nanos','zero_duration_samples'] as const;
function counter(value:unknown):value is string{return typeof value==='string'&&/^(0|[1-9][0-9]{0,39})$/.test(value);}
function validTotals(t:any):boolean{
 if(!t||!counters.every(key=>counter(t[key]))||BigInt(t.timed_payload_bytes_read)>BigInt(t.payload_bytes_read)||BigInt(t.zero_duration_samples)>BigInt(t.sample_count))return false;
 return BigInt(t.active_nanos)===0n?t.average_bytes_per_second===null&&t.timed_payload_bytes_read==='0'&&t.zero_duration_samples===t.sample_count:BigInt(t.zero_duration_samples)<BigInt(t.sample_count)&&counter(t.average_bytes_per_second)&&BigInt(t.average_bytes_per_second)===BigInt(t.timed_payload_bytes_read)*1000000000n/BigInt(t.active_nanos);
}
function validEstimate(row:any):boolean{
 const e=row.current_estimate;if(e===undefined)return true;
 if(!e||typeof e.attempt_id!=='string'||!/^[a-f0-9]{32}$/.test(e.attempt_id)||!['planned_payload_bytes','confirmed_payload_bytes','remaining_payload_bytes','estimated_request_nanos','basis_sample_count','basis_timed_payload_bytes','basis_active_nanos'].every(key=>counter(e[key])))return false;
 const planned=BigInt(e.planned_payload_bytes),confirmed=BigInt(e.confirmed_payload_bytes),remaining=BigInt(e.remaining_payload_bytes),bytes=BigInt(e.basis_timed_payload_bytes),nanos=BigInt(e.basis_active_nanos),samples=BigInt(e.basis_sample_count);
 return remaining>0n&&planned>=confirmed&&planned-confirmed===remaining&&bytes>0n&&nanos>0n&&samples>0n&&samples<=BigInt(row.sample_count)&&bytes<=BigInt(row.timed_payload_bytes_read)&&nanos<=BigInt(row.active_nanos)&&BigInt(e.estimated_request_nanos)===(remaining*nanos+bytes-1n)/bytes;
}
function duration(value:string){const nanos=BigInt(value);if(nanos===0n)return '0 秒';if(nanos<1000000000n)return '不足 1 秒';const seconds=nanos/1000000000n;return (seconds/3600n?seconds/3600n+' 小时 ':'')+(seconds/60n%60n?seconds/60n%60n+' 分 ':'')+seconds%60n+' 秒';}
function rate(t:Totals){return t.average_bytes_per_second===null?'暂无有效计时样本':t.average_bytes_per_second==='0'&&BigInt(t.timed_payload_bytes_read)>0n?'不足 1 B/s':formatBytes(t.average_bytes_per_second)+'/s';}
function invalidate(){generation++;controller?.abort();loading.value=false;}
async function load(){
 if(!active||props.disabled||!expanded.value)return;const request=++generation,batch=props.batchId;controller?.abort();controller=new AbortController();loading.value=true;error.value='';
 try{const response=await fetch('/api/uploads/'+batch+'/transfer-statistics',{credentials:'same-origin',signal:controller.signal});if(!active||request!==generation)return;if(response.status===401){emit('authenticationRequired');throw Error('请重新登录');}if(!response.ok)throw Error(await response.text()||'传输统计不可读');const value=await response.json();if(!active||request!==generation)return;
  if(!value||value.batch_id!==batch||!validTotals(value)||!Number.isSafeInteger(value.total_items)||value.total_items<0||value.total_items>10000||!Array.isArray(value.items)||value.items.length>value.total_items||typeof value.observed_at_utc!=='string'||!Number.isFinite(Date.parse(value.observed_at_utc)))throw Error('传输统计响应无效');
  const ids=new Set<string>();const sums=Object.fromEntries(counters.map(key=>[key,0n]));for(const row of value.items){if(!validTotals(row)||!validEstimate(row)||typeof row.item_id!=='string'||!/^[a-f0-9]{32}$/.test(row.item_id)||ids.has(row.item_id)||typeof row.path!=='string')throw Error('文件传输统计响应无效');ids.add(row.item_id);for(const key of counters)sums[key]+=BigInt(row[key]);}
  if(counters.some(key=>sums[key]!==BigInt(value[key])))throw Error('批次与文件统计不一致');data.value=value;page.value=0;
 }catch(e:any){if(active&&request===generation)error.value=e.message||'传输统计不可读';}finally{if(active&&request===generation)loading.value=false;}
}
function toggle(){expanded.value=!expanded.value;if(expanded.value)load();else invalidate();}
function suspend(){active=false;invalidate();}function restore(e:PageTransitionEvent){if(e.persisted)active=true;}
watch(()=>props.revision,()=>{invalidate();data.value=null;error.value='';page.value=0;});
watch(()=>props.batchId,()=>{invalidate();expanded.value=false;data.value=null;error.value='';page.value=0;});watch(()=>props.disabled,value=>{if(value)invalidate();});
onMounted(()=>{window.addEventListener('pagehide',suspend);window.addEventListener('pageshow',restore);});onUnmounted(()=>{suspend();window.removeEventListener('pagehide',suspend);window.removeEventListener('pageshow',restore);});
</script>
<template><section class="upload-recovery-history" data-testid="upload-transfer-statistics"><button class="button secondary" data-testid="upload-statistics-toggle" :aria-expanded="expanded" :disabled="disabled" @click="toggle">{{expanded?'收起传输统计':'查看传输统计'}}</button><template v-if="expanded"><p class="muted">累计已保存的分片请求样本，包含重试。请求时长含发送及响应等待，不含离线、排队、哈希、合并或请求限速等待；读取字节不等于远端已确认字节。</p><button class="button secondary compact" :disabled="disabled||loading" @click="load">刷新统计快照</button><p v-if="loading" role="status">正在汇总已保存样本…</p><p v-if="error" class="notice danger" role="alert">{{error}}；上次结果仅作历史快照。</p><template v-if="data"><p>读取 UTC：{{data.observed_at_utc}} · 有样本文件 {{data.items.length}} / {{data.total_items}} · 请求样本 {{data.sample_count}}</p><div class="upload-batch-summary"><div><span>已记录请求时长</span><strong>{{duration(data.active_nanos)}}</strong></div><div><span>累计请求均速（含重试）</span><strong>{{rate(data)}}</strong></div><div><span>观察到的文件读取量</span><strong>{{formatBytes(data.payload_bytes_read)}}</strong></div><div><span>零时长样本</span><strong>{{data.zero_duration_samples}}</strong><small>其读取量不参与均速分子</small></div></div><p class="muted">未落盘的中断区间、旧任务或快速创建可能没有样本，不补算时间。仅当前尝试和计划证据有效时显示剩余分片请求估时；不含限速等待、合并或最终核对，不是完成时间或实时倒计时。</p><div v-if="data.items.length" class="event-table-scroll"><table><thead><tr><th>文件</th><th>请求样本</th><th>已记录请求时长</th><th>累计请求均速</th><th>读取量</th><th>本次剩余分片请求估时</th></tr></thead><tbody><tr v-for="row in visible" :key="row.item_id"><td>{{row.path}}</td><td>{{row.sample_count}}</td><td>{{duration(row.active_nanos)}}</td><td>{{rate(row)}}</td><td>{{formatBytes(row.payload_bytes_read)}}</td><td><template v-if="row.current_estimate">{{duration(row.current_estimate.estimated_request_nanos)}}<details><summary>估算依据</summary><small class="cell-sub">尝试 {{row.current_estimate.attempt_id}}</small><small class="cell-sub">计划 {{formatBytes(row.current_estimate.planned_payload_bytes)}} · 已确认 {{formatBytes(row.current_estimate.confirmed_payload_bytes)}} · 剩余 {{formatBytes(row.current_estimate.remaining_payload_bytes)}}</small><small class="cell-sub">依据本次 {{row.current_estimate.basis_sample_count}} 个请求样本</small></details></template><span v-else>暂无可靠估算</span></td></tr></tbody></table></div><p v-if="data.items.length">文件统计第 {{page+1}} 页 · 本页 {{visible.length}} 项</p><button v-if="data.items.length" class="button secondary compact" :disabled="page===0" @click="page--">上一页文件统计</button><button v-if="data.items.length" class="button secondary compact" :disabled="(page+1)*100>=data.items.length" @click="page++">下一页文件统计</button></template></template></section></template>
